window.BC = window.BC || {};
// role: herbivore (nibbles your planted crops), pollinator (visits flowers), neutral.
BC.ANIMALS = [
  { id: 'deer', ride: true, name: 'White-tailed Deer', sci: 'Odocoileus virginianus', biomes: ['temperate', 'prairie', 'wetland'], role: 'herbivore', speed: 1.6,
    body: [0.5, 0.6, 1.1], legH: 0.7, head: [0.3, 0.35, 0.45], colors: { body: '#9a6a3a', head: '#8a5a30', legs: '#6a4a2a', accent: '#f0e8d8' },
    teach: 'Deer browse buds, seedlings and your garden. With wolves and cougars gone, deer numbers in the eastern US are far above historic levels, and forests are losing their wildflowers.',
    facts: ['A deer eats 2 to 4 kg of plants a day and prefers tender growth: tulips, beans, hostas, young oaks.', 'Fencing 2.4 m high, or netting over seedlings, is the only reliable protection.', 'Deer avoid strongly scented or fuzzy plants such as mint, lavender and lamb\'s ear.'] },
  { id: 'cottontail', name: 'Eastern Cottontail', sci: 'Sylvilagus floridanus', biomes: ['temperate', 'prairie'], role: 'herbivore', speed: 2.2,
    body: [0.3, 0.3, 0.45], legH: 0.15, head: [0.22, 0.22, 0.25], colors: { body: '#8a7a60', head: '#8a7a60', legs: '#7a6a50', accent: '#ffffff' },
    teach: 'Rabbits clip seedlings off cleanly at a 45° angle, close to the ground. Deer tear and leave ragged edges. Read the damage to know your visitor.',
    facts: ['A female can raise several litters a year, which is why gardens near brush piles fill with rabbits.', 'Rabbits re-eat their own soft droppings to digest tough plant fibre twice.', 'Low fencing (60 cm, buried 15 cm) keeps them out.'] },
  { id: 'bumblebee', bug: true, name: 'Bumblebee', sci: 'Bombus impatiens', biomes: ['temperate', 'prairie', 'boreal', 'wetland'], role: 'pollinator', flies: true, speed: 2.4, scale: 0.35,
    body: [0.3, 0.25, 0.4], legH: 0, head: [0.15, 0.15, 0.15], colors: { body: '#f0c020', head: '#1a1a1a', legs: '#1a1a1a', accent: '#1a1a1a' },
    teach: 'Bumblebees buzz-pollinate: they grab a flower and vibrate their flight muscles at a frequency that shakes pollen loose. Tomatoes, blueberries and peppers depend on it.',
    facts: ['They fly in cold and rain when honeybees stay home, warming up by shivering to 30 °C before take-off.', 'Only the queen survives winter, hibernating alone underground.', 'Bumblebee colonies are small, a few hundred, and live in old mouse nests.'] },
  { id: 'monarch', bug: true, name: 'Monarch Butterfly', sci: 'Danaus plexippus', biomes: ['temperate', 'prairie'], role: 'pollinator', flies: true, speed: 1.8, scale: 0.4,
    body: [0.08, 0.08, 0.3], legH: 0, head: [0.08, 0.08, 0.08], wings: true, colors: { body: '#1a1a1a', head: '#1a1a1a', legs: '#1a1a1a', accent: '#f08a1a' },
    teach: 'The caterpillar eats only milkweed. The adult flies up to 4,800 km from Canada to a few mountain forests in Mexico, a journey no single butterfly has made before.',
    facts: ['It takes three or four generations to fly north each spring; one super-generation flies all the way south in autumn and lives eight months.', 'Monarch numbers have fallen by about 80% since the 1990s, largely from loss of milkweed in farm fields.', 'Its orange colour warns birds of the milkweed toxins stored in its body.'] },
  { id: 'bison', ride: true, name: 'American Bison', sci: 'Bison bison', biomes: ['prairie'], role: 'grazer', speed: 1.0,
    body: [0.9, 1.0, 1.8], legH: 0.8, head: [0.5, 0.6, 0.6], colors: { body: '#5a4030', head: '#3a2a20', legs: '#3a2a20', accent: '#2a1a10' },
    teach: 'Bison are a keystone species. Their grazing, wallowing and dung create a patchwork of short and tall grass that doubles prairie plant diversity.',
    facts: ['Some 30 to 60 million once roamed; by 1889 fewer than 1,000 were left. Today about 500,000 live, mostly on ranches.', 'They prefer grass and leave wildflowers alone, so bison pastures bloom more than cattle pastures.', 'A bison wallow (dust bath) becomes a seasonal pond that frogs and sedges colonise.'] },
  { id: 'jackrabbit', name: 'Black-tailed Jackrabbit', sci: 'Lepus californicus', biomes: ['desert', 'prairie'], role: 'herbivore', speed: 2.8,
    body: [0.3, 0.35, 0.55], legH: 0.25, head: [0.2, 0.25, 0.3], ears: true, colors: { body: '#a89a7a', head: '#a89a7a', legs: '#8a7a60', accent: '#1a1a1a' },
    teach: 'Its enormous ears are radiators: blood flowing through them dumps heat into the shade without losing a drop of water.',
    facts: ['It is a hare, not a rabbit: born furred, eyes open, ready to run within hours.', 'It gets nearly all its water from plants, including cactus and creosote.', 'It can sprint at 60 km/h and leap 3 m to escape coyotes.'] },
  { id: 'lizard', name: 'Desert Spiny Lizard', sci: 'Sceloporus magister', biomes: ['desert'], role: 'neutral', speed: 2.0, scale: 0.6,
    body: [0.15, 0.1, 0.4], legH: 0.08, head: [0.12, 0.1, 0.15], colors: { body: '#8a8a6a', head: '#7a7a5a', legs: '#6a6a4a', accent: '#3a6ab0' },
    teach: 'Reptiles are ectotherms: they warm up on a sunny rock and retreat into a burrow when the sand exceeds 50 °C. Most desert animals are active only at dawn and dusk.',
    facts: ['It eats insects and so helps control the pests that eat desert plants.', 'Males flash blue belly patches to warn rivals off their territory.', 'Lizards and the plants they shelter under depend on each other: a bush is shade, and the lizard\'s droppings are fertiliser.'] },
  { id: 'chickadee', name: 'Black-capped Chickadee', sci: 'Poecile atricapillus', biomes: ['temperate', 'boreal', 'prairie'], role: 'beneficial', flies: true, speed: 3, scale: 0.3, eats: ['cabbage_white', 'hornworm', 'codling_moth', 'spongy_moth', 'corn_earworm', 'cutworm', 'leafhopper', 'aphid'],
    body: [0.12, 0.12, 0.22], legH: 0, head: [0.1, 0.1, 0.1], beak: true, colors: { body: '#9a9a90', head: '#1a1a1a', legs: '#2a2a2a', accent: '#f0f0f0' },
    teach: 'A pair of chickadees raising chicks collects 6,000 to 9,000 caterpillars in one season. Birds are the biggest caterpillar control on Earth, and they need native trees: an oak feeds 500 kinds of caterpillar, a lawn feeds none.',
    facts: ['It hides thousands of seeds each autumn and remembers where; its hippocampus grows in October.', 'The number of "dee" notes in its call rises with the danger: a perched owl gets four or five.', 'A feeder brings them in, but it is caterpillars, not seed, that they feed their young.'] },
  { id: 'hummingbird', name: 'Ruby-throated Hummingbird', sci: 'Archilochus colubris', biomes: ['temperate', 'rainforest', 'desert'], role: 'pollinator', flies: true, speed: 3.5, scale: 0.35,
    body: [0.1, 0.1, 0.25], legH: 0, head: [0.08, 0.08, 0.12], beak: true, colors: { body: '#3a8a4a', head: '#2a7a3a', legs: '#1a1a1a', accent: '#d8203a' },
    teach: 'Hummingbirds see red and have no sense of smell, so hummingbird flowers are red, tubular, scentless and full of dilute nectar.',
    facts: ['Its heart beats 1,200 times a minute and it must eat half its weight in sugar daily.', 'It crosses the Gulf of Mexico in one 800 km non-stop flight each autumn.', 'Pollen sticks to its forehead and is carried flower to flower as it feeds.'] },
  { id: 'toucan', name: 'Toco Toucan', sci: 'Ramphastos toco', biomes: ['rainforest'], role: 'neutral', flies: true, speed: 2.2, scale: 0.6,
    body: [0.25, 0.3, 0.45], legH: 0.1, head: [0.22, 0.25, 0.25], beak: true, colors: { body: '#1a1a1a', head: '#1a1a1a', legs: '#4a6ab0', accent: '#f0a020' },
    teach: 'Toucans are seed dispersers. They swallow fruit whole and drop the seeds far from the parent tree, planting the forest as they go.',
    facts: ['The huge beak is a radiator (like a jackrabbit\'s ears) that can dump heat, and it is light as honeycomb inside.', 'Toucans nest in tree holes, so a forest needs old trees for them to breed.', 'Most tropical trees depend on animals, not wind, to spread their seeds.'] },
  { id: 'dart_frog', name: 'Poison Dart Frog', sci: 'Dendrobates tinctorius', biomes: ['rainforest'], role: 'neutral', speed: 1.2, scale: 0.4,
    body: [0.15, 0.1, 0.2], legH: 0.06, head: [0.12, 0.08, 0.1], colors: { body: '#1a3ad8', head: '#1a3ad8', legs: '#1a1a1a', accent: '#f0d020' },
    teach: 'It carries its tadpoles one by one up a tree and drops each into the water tank of a bromeliad, then returns to feed them unfertilised eggs.',
    facts: ['Its poison comes from the ants and mites it eats; frogs raised in captivity are harmless.', 'Bright colours warn predators. This is called aposematism, the same strategy as the monarch.', 'Frogs breathe partly through their skin, which makes them early victims of pollution and a warning sign for ecosystem health.'] },
  { id: 'moose', ride: true, name: 'Moose', sci: 'Alces alces', biomes: ['boreal', 'wetland'], role: 'herbivore', speed: 1.3,
    body: [0.8, 1.0, 1.9], legH: 1.1, head: [0.4, 0.5, 0.8], antlers: true, colors: { body: '#3a2a20', head: '#4a3a2a', legs: '#5a4a3a', accent: '#8a7a6a' },
    teach: 'The word moose is Algonquian for twig eater. In summer it wades into ponds for water lilies, which are rich in the sodium its diet of twigs lacks.',
    facts: ['An adult eats 20 to 30 kg of browse a day: willow, birch, aspen and your saplings.', 'Moose can dive 5 m to pull up aquatic plants.', 'Warming winters let ticks survive; some moose now carry 50,000 ticks and die of blood loss.'] },
  { id: 'hare', name: 'Snowshoe Hare', sci: 'Lepus americanus', biomes: ['boreal'], role: 'herbivore', speed: 2.5,
    body: [0.3, 0.3, 0.5], legH: 0.2, head: [0.2, 0.22, 0.28], ears: true, colors: { body: '#e8e8e0', head: '#e8e8e0', legs: '#d8d8d0', accent: '#1a1a1a' },
    teach: 'Its fur turns white in winter and brown in summer, triggered by day length. It eats bark and buds, girdling young trees under the snow.',
    facts: ['Hare and lynx populations rise and fall together in a famous ten-year cycle recorded in Hudson\'s Bay Company fur records since the 1800s.', 'Huge hind feet spread its weight on snow like snowshoes.', 'Shorter snow seasons now leave white hares exposed on brown ground, an early casualty of climate change.'] },
  { id: 'frog', name: 'Green Frog', sci: 'Lithobates clamitans', biomes: ['wetland', 'temperate'], role: 'neutral', speed: 1.4, scale: 0.5,
    body: [0.18, 0.12, 0.25], legH: 0.06, head: [0.15, 0.1, 0.12], colors: { body: '#4a8a3a', head: '#5a9a3a', legs: '#3a7a2a', accent: '#e8e0a0' },
    teach: 'Frogs need wetlands twice: as tadpoles that eat algae in the water and as adults that eat insects on land. Draining a marsh removes both.',
    facts: ['Its call sounds like a plucked banjo string.', 'Tadpoles are grazers that keep algae from choking the pond; adults eat mosquitoes.', 'Amphibians are the most threatened vertebrate group on Earth; about 40% of species are declining.'] },
  { id: 'dragonfly', bug: true, name: 'Common Green Darner', sci: 'Anax junius', biomes: ['wetland', 'prairie'], role: 'neutral', flies: true, speed: 3.0, scale: 0.4,
    body: [0.05, 0.05, 0.35], legH: 0, head: [0.1, 0.1, 0.1], wings: true, colors: { body: '#3a6ad8', head: '#4a9a3a', legs: '#1a1a1a', accent: '#c8d8e8' },
    teach: 'A dragonfly spends up to two years as an underwater nymph eating mosquito larvae, then a few weeks in the air eating adult mosquitoes. Wetland plants give the nymphs cover.',
    facts: ['It catches 95% of the prey it chases, the best hunting record of any animal.', 'Dragonflies migrate too: green darners travel between Canada and the Gulf over several generations.', 'Nymphs climb a cattail stem to moult into the winged adult, leaving a ghostly skin behind.'] },
  { id: 'heron', name: 'Great Blue Heron', sci: 'Ardea herodias', biomes: ['wetland', 'temperate', 'prairie'], role: 'neutral', speed: 0.8, scale: 0.9,
    body: [0.3, 0.35, 0.6], legH: 0.8, head: [0.15, 0.15, 0.3], beak: true, colors: { body: '#7a8a9a', head: '#e8e8e8', legs: '#5a5a4a', accent: '#1a1a1a' },
    teach: 'A top predator of the marsh. Herons need shallow water to hunt, tall trees to nest in colonies, and clean water with fish: three tests of a healthy wetland.',
    facts: ['It stands motionless for minutes, then strikes in a quarter of a second.', 'Herons helped push through bird protection laws in 1900 after plume hunters nearly wiped out egrets for hats.', 'Nest colonies (heronries) can hold hundreds of nests in a few cypress trees.'] },
  { id: 'earthworm', bug: true, name: 'Earthworm', sci: 'Lumbricus terrestris', biomes: ['temperate', 'prairie', 'wetland'], role: 'soil', hidden: true,
    teach: 'Darwin called earthworms the most important animal in the history of the world. They drag leaves underground, mix the horizons and leave casts richer than the soil they ate.',
    facts: ['One hectare of good pasture can hold 1 to 3 million worms, turning over 40 tonnes of soil a year.', 'The common earthworm is European; it arrived in North America in ships\' ballast. In northern forests that evolved without worms, it is eating the leaf litter that wildflowers need.', 'Worm burrows let rain soak in instead of running off, which is why worm-rich soil rarely floods.'] },
  // ---------- additional animals ----------
  { id: 'red_fox', name: 'Red Fox', sci: 'Vulpes vulpes', biomes: ['temperate', 'prairie', 'boreal', 'tundra'], role: 'neutral', speed: 2.4,
    body: [0.28, 0.3, 0.7], legH: 0.3, head: [0.22, 0.22, 0.3], ears: true, colors: { body: '#c8602a', head: '#c8602a', legs: '#2a1a10', accent: '#ffffff' },
    teach: 'A fox eats mice, voles and rabbits, which makes it the gardener\'s friend. It also eats berries and buries surplus food, planting seeds as it goes.',
    facts: ['A fox can hear a mouse under 30 cm of snow and pounces in a high arc, often aligned with the Earth\'s magnetic field.', 'The most widespread wild carnivore on Earth, from the Arctic to North Africa and city parks.', 'Fox dens are often old badger or woodchuck burrows under tree roots.'] },
  { id: 'wild_turkey', name: 'Wild Turkey', sci: 'Meleagris gallopavo', biomes: ['temperate', 'prairie'], role: 'herbivore', speed: 1.5,
    body: [0.45, 0.5, 0.7], legH: 0.4, head: [0.15, 0.2, 0.25], beak: true, colors: { body: '#4a3a2a', head: '#c05a6a', legs: '#9a6a4a', accent: '#d8a85a' },
    teach: 'Turkeys scratch up acorns, seeds and your newly planted beans. Nearly extinct by 1930, they have been restored to every state but Alaska.',
    facts: ['A turkey can run 40 km/h and fly 90 km/h for short bursts, and roosts in trees at night.', 'The Aztecs domesticated it long before Europeans arrived; the bird came to England via Turkish merchants, hence the name.', 'Turkeys see in colour and ultraviolet and have nearly 360-degree vision.'] },
  { id: 'black_bear', ride: true, name: 'American Black Bear', sci: 'Ursus americanus', biomes: ['temperate', 'boreal'], role: 'neutral', speed: 1.4,
    body: [0.8, 0.9, 1.5], legH: 0.6, head: [0.45, 0.45, 0.55], colors: { body: '#1a1510', head: '#1a1510', legs: '#1a1510', accent: '#8a6a4a' },
    teach: 'Mostly vegetarian: berries, acorns, beechnuts, grubs, and in autumn 20,000 calories a day to prepare for a winter without eating, drinking or passing waste.',
    facts: ['Bears are major seed dispersers; a single bear scat can hold thousands of berry seeds, pre-fertilised.', 'A bear remembers a food source for years, which is why unsecured compost and bird feeders cause trouble.', 'Cubs are born in the den in January weighing less than a can of soup.'] },
  { id: 'box_turtle', name: 'Eastern Box Turtle', sci: 'Terrapene carolina', biomes: ['temperate'], role: 'neutral', speed: 0.4, scale: 0.5,
    body: [0.3, 0.2, 0.4], legH: 0.08, head: [0.12, 0.1, 0.15], colors: { body: '#5a4a2a', head: '#8a6a3a', legs: '#6a5a3a', accent: '#e8a830' },
    teach: 'A land turtle that can seal itself completely inside a hinged shell. It eats mayapple fruit and mushrooms and spreads their seeds and spores.',
    facts: ['Box turtles live 50 to 100 years and rarely leave an area the size of two football fields in that whole time.', 'Moving one "to safety" across a road in the wrong direction can doom it: it will spend years trying to get home.', 'Their numbers are falling from roads, mowers and collection for pets.'] },
  { id: 'pronghorn', name: 'Pronghorn', sci: 'Antilocapra americana', biomes: ['prairie', 'desert'], role: 'grazer', speed: 3.5,
    body: [0.45, 0.6, 1.1], legH: 0.75, head: [0.25, 0.3, 0.4], antlers: true, colors: { body: '#c8a070', head: '#c8a070', legs: '#b89060', accent: '#ffffff' },
    teach: 'The fastest land animal in the Americas, 90 km/h, with no living predator that fast. It evolved to outrun the American cheetah, extinct for 12,000 years.',
    facts: ['It is not an antelope; its closest living relatives are giraffes.', 'Pronghorn eat sagebrush and forbs that cattle avoid, so they fit alongside ranching.', 'They cannot jump fences well; wildlife-friendly fences leave a gap at the bottom for them to crawl under.'] },
  { id: 'prairie_dog', name: 'Black-tailed Prairie Dog', sci: 'Cynomys ludovicianus', biomes: ['prairie'], role: 'herbivore', speed: 1.8, scale: 0.55,
    body: [0.25, 0.25, 0.4], legH: 0.1, head: [0.18, 0.18, 0.22], colors: { body: '#c8a878', head: '#c8a878', legs: '#a88858', accent: '#1a1a1a' },
    teach: 'A keystone species. Its burrow towns aerate and fertilise the soil, its grazing keeps grass short and nutritious for bison, and 150 other species use its tunnels.',
    facts: ['Prairie dogs have one of the most complex animal languages known, with different calls for a hawk, a coyote and a tall human in a yellow shirt.', 'Towns once covered 40 million hectares; one in Texas held an estimated 400 million animals. Poisoning reduced them by 98%.', 'The black-footed ferret, America\'s rarest mammal, eats almost nothing else.'] },
  { id: 'roadrunner', name: 'Greater Roadrunner', sci: 'Geococcyx californianus', biomes: ['desert'], role: 'neutral', speed: 3.0, scale: 0.6,
    body: [0.18, 0.25, 0.5], legH: 0.25, head: [0.14, 0.14, 0.2], beak: true, colors: { body: '#6a5a4a', head: '#5a4a3a', legs: '#8a8a7a', accent: '#3a6ab0' },
    teach: 'A ground cuckoo that runs down lizards, scorpions and rattlesnakes at 30 km/h. It sunbathes each cold morning, spreading its back feathers to warm a patch of black skin.',
    facts: ['It reabsorbs water from its droppings and excretes salt through a gland near its eyes, so it rarely needs to drink.', 'Pairs mate for life and the male brings a lizard as a courtship gift.', 'It can fly, barely, and prefers to glide down from a perch.'] },
  { id: 'desert_tortoise', name: 'Desert Tortoise', sci: 'Gopherus agassizii', biomes: ['desert'], role: 'herbivore', speed: 0.3, scale: 0.6,
    body: [0.35, 0.22, 0.45], legH: 0.1, head: [0.14, 0.12, 0.18], colors: { body: '#8a7a5a', head: '#9a8a6a', legs: '#7a6a4a', accent: '#6a5a3a' },
    teach: 'Spends 95% of its life underground in burrows up to 10 m long that shelter owls, snakes and rabbits too. It stores a year\'s water in its bladder.',
    facts: ['Never pick one up: a frightened tortoise empties its bladder and may die of dehydration before the next rain.', 'It eats spring wildflowers and grasses and can live 80 years, but ravens attracted by human garbage eat most hatchlings.', 'Tortoises dig and fertilise, spreading the seeds of the plants they eat along their trails.'] },
  { id: 'capybara', ride: true, name: 'Capybara', sci: 'Hydrochoerus hydrochaeris', biomes: ['rainforest', 'wetland'], role: 'herbivore', speed: 1.3,
    body: [0.6, 0.6, 1.1], legH: 0.4, head: [0.35, 0.35, 0.45], colors: { body: '#9a7a4a', head: '#9a7a4a', legs: '#7a5a3a', accent: '#1a1a1a' },
    teach: 'The world\'s largest rodent, 60 kg of grass-eating riverbank engineer. Herds graze wetland edges and keep them open, and nearly every animal in the forest seems happy to sit on one.',
    facts: ['Eyes, ears and nostrils sit on top of the head so it can hide under water with only those showing, for up to five minutes.', 'Capybaras eat their own soft droppings each morning to digest grass fully, like rabbits do.', 'In parts of South America they are ranched for meat, and the Catholic Church once classed them as fish for Lent.'] },
  { id: 'sloth', name: 'Brown-throated Sloth', sci: 'Bradypus variegatus', biomes: ['rainforest'], role: 'neutral', speed: 0.2, scale: 0.7,
    body: [0.3, 0.35, 0.5], legH: 0.35, head: [0.2, 0.2, 0.2], colors: { body: '#8a8a6a', head: '#9a9a7a', legs: '#7a7a5a', accent: '#3a3a2a' },
    teach: 'A sloth eats leaves so low in energy that it moves slowly to survive, and its fur is a garden: algae grow in grooves on each hair and moths live in it, which help the algae grow.',
    facts: ['It climbs down to the ground once a week to defecate at the base of its tree, fertilising it and giving the moths a place to breed.', 'Its stomach takes a month to digest a meal and makes up a third of its weight.', 'Sloths can turn their heads 270 degrees and swim three times faster than they walk.'] },
  { id: 'scarlet_macaw', name: 'Scarlet Macaw', sci: 'Ara macao', biomes: ['rainforest'], role: 'neutral', flies: true, speed: 2.6, scale: 0.6,
    body: [0.18, 0.2, 0.45], legH: 0.08, head: [0.16, 0.18, 0.2], beak: true, wings: true, colors: { body: '#e02020', head: '#e02020', legs: '#3a3a3a', accent: '#f0c020' },
    teach: 'A parrot that cracks the hardest rainforest nuts and visits clay cliffs to eat soil, which binds the toxins in unripe seeds it eats before other animals can.',
    facts: ['Macaws pair for life and can live 60 years. Chicks need three months in a tree hole, so old hollow trees are essential.', 'It is a seed predator, not a disperser: it crushes most seeds, but drops enough to plant new trees far from the parent.', 'Captured for the pet trade, it vanished from most of Central America; Costa Rica is bringing it back.'] },
  { id: 'beaver', name: 'North American Beaver', sci: 'Castor canadensis', biomes: ['wetland', 'boreal', 'temperate'], role: 'herbivore', speed: 1.0,
    body: [0.4, 0.4, 0.8], legH: 0.15, head: [0.25, 0.25, 0.3], colors: { body: '#5a3a20', head: '#5a3a20', legs: '#3a2a18', accent: '#2a2018' },
    teach: 'The only animal besides us that reshapes whole landscapes. A beaver dam creates a pond, the pond becomes a wetland, the wetland becomes a meadow, and the meadow becomes forest: succession in fast forward.',
    facts: ['Its orange teeth are iron-hardened and never stop growing; it fells aspen, willow and birch and eats the bark.', 'Beaver ponds raise the water table, filter silt, slow floods and keep streams flowing through drought.', 'Trapped nearly to extinction for hats by 1900, beavers are now being reintroduced to restore dried-out valleys.'] },
  { id: 'caribou', ride: true, name: 'Woodland Caribou', sci: 'Rangifer tarandus caribou', biomes: ['tundra', 'boreal'], role: 'herbivore', speed: 1.8,
    body: [0.7, 0.8, 1.6], legH: 0.9, head: [0.35, 0.4, 0.6], antlers: true, colors: { body: '#8a7a6a', head: '#7a6a5a', legs: '#5a4a3a', accent: '#e8e0d0' },
    teach: 'The only deer in which females grow antlers. In winter it lives almost entirely on reindeer lichen, which it smells through the snow and digs out with shovel-shaped hooves.',
    facts: ['Woodland caribou need old forests with deep lichen mats; logging and roads let wolves and moose in, and herds across Canada are shrinking.', 'Hollow hairs trap air so a caribou floats high when it swims across rivers.', 'Its clicking tendons let a herd keep together in a blizzard by sound alone.'] },
  { id: 'alligator', ride: true, name: 'American Alligator', sci: 'Alligator mississippiensis', biomes: ['wetland'], role: 'neutral', speed: 1.2, noLeash: true,
    body: [0.5, 0.35, 1.8], legH: 0.15, head: [0.3, 0.25, 0.7], colors: { body: '#3a4a2a', head: '#3a4a2a', legs: '#2a3a1a', accent: '#c8c8a0' },
    teach: 'An ecosystem engineer of the Everglades. In the dry season it digs "gator holes" that hold the last water, keeping fish, turtles and wading birds alive until the rains return.',
    facts: ['Nest temperature decides the sex of the hatchlings: above 34 °C mostly males, below 30 °C mostly females.', 'Hunted to near extinction by the 1960s, it recovered under the Endangered Species Act and was delisted in 1987.', 'Keep your distance and never feed one; a fed gator loses its fear of people and has to be destroyed.'] },
  // ---------- bats, fish and a crab ----------
  { id: 'little_brown_bat', name: 'Little Brown Bat', sci: 'Myotis lucifugus', biomes: ['temperate', 'boreal', 'wetland'], role: 'neutral', flies: true, speed: 3.2, scale: 0.35, nocturnal: true,
    body: [0.1, 0.1, 0.18], legH: 0, head: [0.09, 0.09, 0.1], wings: true, colors: { body: '#5a4a3a', head: '#5a4a3a', legs: '#2a2a2a', accent: '#3a3028' },
    teach: 'One bat eats half its weight in insects a night, including moths whose caterpillars are crop pests. Its guano, under a roost, is one of the richest natural fertilisers.',
    facts: ['White-nose syndrome, a fungus from Europe, has killed over 90% of little brown bats in eastern North America since 2006.', 'Bats are worth an estimated 3 to 50 billion dollars a year to US farms in pest control.', 'A bat house on a sunny pole gives them a roost where old hollow trees have gone.'] },
  { id: 'long_nosed_bat', name: 'Lesser Long-nosed Bat', sci: 'Leptonycteris yerbabuenae', biomes: ['desert'], role: 'pollinator', flies: true, speed: 3.4, scale: 0.4, nocturnal: true,
    body: [0.12, 0.12, 0.22], legH: 0, head: [0.1, 0.1, 0.14], wings: true, colors: { body: '#8a7a6a', head: '#8a7a6a', legs: '#2a2a2a', accent: '#5a4a3a' },
    teach: 'The pollinator of saguaro, organ pipe cactus and agave. It migrates 1,200 km from Mexico following the "nectar corridor" of blooming cacti north each spring.',
    facts: ['Its tongue is as long as its body. Tequila exists because of it: no bat, no agave seeds.', 'Removed from the US endangered list in 2018 after roosts were protected, the first bat ever delisted for recovery.', 'Guano beneath its roost caves is mined as fertiliser.'] },
  { id: 'koi', name: 'Koi', sci: 'Cyprinus rubrofuscus', biomes: [], hidden: true, role: 'neutral', aquatic: true, speed: 0.9, scale: 0.7,
    body: [0.12, 0.26, 0.5], legH: 0, head: [0.08, 0.16, 0.1], colors: { body: '#f08030', head: '#f4f0e8', legs: '#2a2a2a', accent: '#f8f4ee' },
    teach: 'Amur carp bred for colour by Japanese rice farmers since the 1820s; a kohaku is white with red patches, a showa adds black. Koi live 40 years, grow to 80 cm and graze algae, insect larvae and pond plants, so they are a working part of a pond, not just decoration.',
    facts: ['Hanako, a scarlet koi, was reported to have lived 226 years, aged by counting scale rings.', 'They go torpid under 10 C and stop eating; do not feed them in winter.', 'Herons take koi from shallow ponds; a deep end and a lily pad give cover.'] },
  { id: 'bluegill', name: 'Bluegill', sci: 'Lepomis macrochirus', biomes: ['wetland', 'temperate', 'prairie'], role: 'neutral', aquatic: true, speed: 1.4, scale: 0.4,
    body: [0.08, 0.22, 0.3], legH: 0, head: [0.07, 0.15, 0.1], colors: { body: '#4a7a6a', head: '#3a6a5a', legs: '#2a2a2a', accent: '#e8a030' },
    teach: 'The pond sunfish every child catches first. Males fan out a nest in the shallows and guard it. Fish scraps buried under crops were the first fertiliser of the Americas.',
    facts: ['A bluegill can lay 50,000 eggs; without bass to eat them, ponds fill with stunted fish.', 'They eat mosquito larvae and are stocked for that reason.', 'The ear flap is blue-black; the orange breast marks a breeding male.'] },
  { id: 'catfish', name: 'Channel Catfish', sci: 'Ictalurus punctatus', biomes: ['wetland', 'prairie', 'temperate'], role: 'neutral', aquatic: true, speed: 1.2, scale: 0.6,
    body: [0.15, 0.2, 0.6], legH: 0, head: [0.14, 0.15, 0.2], colors: { body: '#5a5a5a', head: '#4a4a4a', legs: '#2a2a2a', accent: '#c8c8b0' },
    teach: 'Whiskers (barbels) covered in taste buds let it find food in muddy water by night. Its whole skin tastes.',
    facts: ['The most farmed fish in the United States, raised in Mississippi ponds.', 'Males guard eggs in hollow logs and undercut banks.', 'Fish emulsion is made from the parts filleting leaves behind.'] },
  { id: 'desert_pupfish', name: 'Desert Pupfish', sci: 'Cyprinodon macularius', biomes: ['desert'], role: 'neutral', aquatic: true, speed: 1.6, scale: 0.35,
    body: [0.08, 0.2, 0.3], legs: 0, legH: 0, head: [0.07, 0.14, 0.1], colors: { body: '#5a8ab8', head: '#4a7aa8', legs: '#2a2a2a', accent: '#e8eef4' },
    teach: 'A thumb-sized fish that lives where no fish should: desert springs and pools at 40 C, water saltier than the sea, oxygen almost gone. Each spring in the Mojave and Sonoran deserts has its own pupfish, stranded when the Ice Age lakes dried 10,000 years ago. Breeding males turn electric blue.',
    facts: ['The Devils Hole pupfish lives in one pool in Nevada; its whole species is a few hundred fish.', 'They tolerate temperature swings that would kill a trout in minutes.', 'Pumping groundwater for farms lowers the springs; pupfish were among the first animals protected by the Endangered Species Act.'] },
  { id: 'trout', name: 'Brook Trout', sci: 'Salvelinus fontinalis', biomes: ['boreal', 'temperate'], role: 'neutral', aquatic: true, speed: 1.8, scale: 0.5,
    body: [0.1, 0.18, 0.45], legH: 0, head: [0.09, 0.13, 0.14], colors: { body: '#3a6a4a', head: '#3a5a4a', legs: '#2a2a2a', accent: '#e86a3a' },
    teach: 'A char of cold, clean, shaded streams. Where hemlocks are cut and the water warms past 20 °C, brook trout vanish: a living thermometer for the forest.',
    facts: ['Red spots with blue halos and white-edged fins; males turn orange in the autumn spawn.', 'Beaver ponds and fallen logs make the deep cold pools it needs.', 'Acid rain wiped it from hundreds of Adirondack lakes in the 1970s.'] },
  { id: 'piranha', name: 'Red-bellied Piranha', sci: 'Pygocentrus nattereri', biomes: ['rainforest'], role: 'neutral', aquatic: true, speed: 1.6, scale: 0.45,
    body: [0.1, 0.22, 0.3], legH: 0, head: [0.09, 0.16, 0.1], colors: { body: '#6a7a7a', head: '#5a6a6a', legs: '#2a2a2a', accent: '#d83a2a' },
    teach: 'Mostly a scavenger and a nibbler of fins and seeds; the feeding frenzies of film happen only when a shoal is trapped in a shrinking dry-season pool. Many Amazon fish eat fruit and plant the forest.',
    facts: ['Teeth are interlocking triangles that replace in quarters, one quadrant at a time.', 'They bark when caught, using the swim bladder.', 'Amazon river people eat them in soup and use the jaws as scissors.'] },
  { id: 'blue_crab', name: 'Blue Crab', sci: 'Callinectes sapidus', biomes: ['wetland'], role: 'neutral', aquatic: true, speed: 1.0, scale: 0.45,
    body: [0.35, 0.08, 0.22], legH: 0.05, head: [0.1, 0.06, 0.08], colors: { body: '#4a6a5a', head: '#4a6a5a', legs: '#3a6ab8', accent: '#e85a2a' },
    teach: 'Callinectes sapidus means beautiful savoury swimmer. It lives among mangrove roots and marsh grass, and its shell is chitin, which gardeners grind into a fertiliser that also fights nematodes.',
    facts: ['A female mates once in her life, right after her final moult while her shell is soft.', 'Chesapeake Bay crab catches track the health of its eelgrass beds.', 'Crabs are omnivores that clean up dead fish and keep marsh snails from overgrazing the cordgrass.'] },

  // ---------- more land, water and sky: mounts, pack animals, waterfowl, raptors, songbirds, river and sea life ----------
  { id: 'horse', name: 'Horse', sci: 'Equus ferus caballus', biomes: ['prairie', 'temperate', 'desert'], role: 'grazer', speed: 2.6, ride: true,
    body: [0.55, 0.7, 1.4], legH: 0.85, head: [0.3, 0.4, 0.55], colors: { body: '#8a5a3a', head: '#7a4a2a', legs: '#5a3a22', accent: '#2a1a10' },
    teach: 'Horses evolved in North America, crossed to Asia, died out here and came back with the Spanish in 1519. A horse grazes 16 hours a day and its manure, hot with nitrogen, is the classic garden fertiliser once it has composted for a season.',
    facts: ['Fresh horse manure is full of weed seeds; hot composting kills them.', 'A horse eats about 10 kg of grass a day and needs a hectare or two of pasture.', 'Tap it with your hand to ride. W to go, Space to get off. Hitch a wagon to carry cargo.'] },
  { id: 'donkey', name: 'Donkey', sci: 'Equus africanus asinus', biomes: ['desert', 'prairie'], role: 'grazer', speed: 1.9, ride: true,
    body: [0.42, 0.5, 1.0], legH: 0.6, head: [0.24, 0.3, 0.45], ears: true, colors: { body: '#8a8078', head: '#7a7068', legs: '#6a6058', accent: '#f0ece0' },
    teach: 'Domesticated in Africa 6,000 years ago from the wild ass, the donkey carried the first farmers\' grain and still works where tractors cannot go. It browses thorny scrub a horse refuses and drinks a quarter of the water.',
    facts: ['A donkey can carry a third of its weight all day.', 'The long ears shed heat and hear a bray from 3 km away.', 'Its manure is drier and milder than horse manure; good straight onto a bed in autumn.'] },
  { id: 'camel', name: 'Dromedary Camel', sci: 'Camelus dromedarius', biomes: ['desert'], role: 'grazer', speed: 2.0, ride: true,
    body: [0.6, 0.8, 1.6], legH: 1.0, head: [0.3, 0.35, 0.6], colors: { body: '#c8a060', head: '#b89050', legs: '#a88040', accent: '#8a6a30' },
    teach: 'The hump is fat, not water: a week of food for crossing country with none. A camel drinks 100 litres in ten minutes, and its lips and tongue eat thorn scrub and saltbush no other grazer touches.',
    facts: ['Camels were imported to the American Southwest by the US Army in 1856; feral herds roamed until the 1930s.', 'Camel dung dries so fast it is burned as fuel the same day.', 'It can ride you across the whole desert. Tap to mount.'] },
  { id: 'elk', name: 'Elk (Wapiti)', sci: 'Cervus canadensis', biomes: ['temperate', 'boreal', 'prairie'], role: 'herbivore', speed: 1.8, ride: true, antlers: true,
    body: [0.6, 0.75, 1.4], legH: 0.9, head: [0.3, 0.4, 0.55], colors: { body: '#9a7a5a', head: '#6a4a30', legs: '#5a3a22', accent: '#e8d8b8' },
    teach: 'The second largest deer, and the loudest: a bull\'s bugle carries for miles in autumn. Elk strip aspen bark and browse willow so hard that when wolves returned to Yellowstone and moved the elk on, the streamside willows and beavers came back.',
    facts: ['Antlers grow 2 cm a day in summer, the fastest growing bone known, and drop every spring.', 'A herd keeps meadows open; without elk, forest closes in.', 'Pale rump patch: a flag the herd follows through dark timber.'] },
  { id: 'river_otter', name: 'North American River Otter', sci: 'Lontra canadensis', biomes: ['wetland', 'temperate', 'boreal'], role: 'neutral', speed: 2.2, scale: 0.6,
    body: [0.22, 0.22, 0.8], legH: 0.12, head: [0.18, 0.16, 0.22], colors: { body: '#4a3a2a', head: '#5a4a3a', legs: '#3a2a1a', accent: '#c8b8a0' },
    teach: 'An otter in a river means the water is clean and full of fish. They vanished from polluted rivers in the 20th century and have returned to most of them since the Clean Water Act.',
    facts: ['Otters slide down mudbanks for fun and hunt crayfish, frogs and slow fish.', 'The densest fur of any mammal: a million hairs per square inch.', 'A family\'s latrine on a bank fertilises a patch that grows lush nettles.'] },
  { id: 'raccoon', name: 'Raccoon', sci: 'Procyon lotor', biomes: ['temperate', 'wetland', 'prairie'], role: 'herbivore', speed: 1.6, scale: 0.6,
    body: [0.3, 0.3, 0.6], legH: 0.2, head: [0.24, 0.2, 0.26], ears: true, colors: { body: '#6a6a66', head: '#8a8a86', legs: '#3a3a3a', accent: '#1a1a1a' },
    teach: 'The masked raider of sweetcorn: it knows the night the ears ripen better than you do. Its paws are nearly hands, which is why no latch stops it. Raccoons also spread seeds in their droppings, especially persimmon and pawpaw.',
    facts: ['Harvest corn the day the silks brown or the raccoons will.', 'They wash food not to clean it but to feel it: wet paws are more sensitive.', 'An electric strand at 15 cm is the only fence that works.'] },
  { id: 'skunk', name: 'Striped Skunk', sci: 'Mephitis mephitis', biomes: ['prairie', 'temperate'], role: 'beneficial', speed: 1.0, scale: 0.55, eats: ['japanese_beetle', 'cutworm', 'wireworm', 'root_maggot', 'grasshopper'],
    body: [0.26, 0.26, 0.55], legH: 0.14, head: [0.2, 0.18, 0.24], colors: { body: '#1a1a1a', head: '#1a1a1a', legs: '#111', accent: '#f4f4f4' },
    teach: 'The small cone-shaped holes in your lawn at dawn are a skunk digging grubs, and it is doing you a favour: one skunk eats thousands of beetle larvae a season. It only sprays when cornered, and it gives three warnings first.',
    facts: ['Skunks eat yellowjacket nests, grubs, mice and fallen fruit.', 'Tomato juice does not remove the smell; peroxide, baking soda and soap does.', 'They are the main pollinator of nothing and the main predator of lawn grubs.'] },
  { id: 'coyote', name: 'Coyote', sci: 'Canis latrans', biomes: ['prairie', 'desert', 'temperate'], role: 'neutral', speed: 2.4, scale: 0.8,
    body: [0.3, 0.38, 0.8], legH: 0.42, head: [0.22, 0.22, 0.4], ears: true, colors: { body: '#a89070', head: '#9a8060', legs: '#8a7050', accent: '#e8e0d0' },
    teach: 'The one predator that thrived as the continent was farmed. Coyotes keep rabbits and rodents down, and a third of their diet is fruit: persimmon, juniper berries, prickly pear, which they plant in their scat.',
    facts: ['A coyote pair holds a territory and sings at dusk to say so.', 'They eat 1,800 rodents a year each: worth more to a farm than they cost.', 'Where coyotes are removed, feral cats and raccoons multiply and songbirds decline.'] },
  { id: 'gray_wolf', name: 'Gray Wolf', sci: 'Canis lupus', biomes: ['boreal', 'tundra'], role: 'neutral', speed: 2.4,
    body: [0.4, 0.5, 1.0], legH: 0.55, head: [0.26, 0.28, 0.5], ears: true, colors: { body: '#7a7a78', head: '#8a8a88', legs: '#5a5a58', accent: '#e8e8e8' },
    teach: 'Wolves change where deer and elk dare to graze, and that changes which plants grow. In Yellowstone their return let willow and aspen regrow along rivers, which brought back beavers, songbirds and even changed the course of streams.',
    facts: ['A pack is a family: parents and their grown pups.', 'Wolves kill about one in ten of the deer they chase; the rest are too fit.', 'They were gone from the lower 48 states by 1960 and are back in a dozen of them.'] },
  { id: 'bighorn', ride: true, name: 'Desert Bighorn Sheep', sci: 'Ovis canadensis nelsoni', biomes: ['desert'], role: 'grazer', speed: 1.8,
    body: [0.45, 0.55, 1.0], legH: 0.6, head: [0.28, 0.3, 0.4], antlers: true, colors: { body: '#a08868', head: '#908060', legs: '#7a6a50', accent: '#c8b088' },
    teach: 'Lives on cliffs no predator can follow, and goes days without water by eating cactus and succulents. The curled horns are permanent and grow a ring a year, so you can age a ram like a tree.',
    facts: ['Rams clash horns at 30 km/h; a double skull and a thick neck absorb it.', 'They need open sightlines; shrubs encroaching on grassland hide lions and push the sheep out.', 'Domestic sheep diseases nearly wiped them out; herds are kept apart.'] },
  { id: 'armadillo', name: 'Nine-banded Armadillo', sci: 'Dasypus novemcinctus', biomes: ['prairie', 'desert', 'temperate'], role: 'beneficial', speed: 1.2, scale: 0.5, eats: ['japanese_beetle', 'cutworm', 'wireworm', 'root_maggot', 'grasshopper'],
    body: [0.26, 0.22, 0.55], legH: 0.1, head: [0.14, 0.12, 0.3], colors: { body: '#9a8a7a', head: '#8a7a6a', legs: '#7a6a5a', accent: '#6a5a4a' },
    teach: 'An armoured insect-eater that has walked north from Texas to Nebraska in a century. It digs up lawns for grubs and leaves the soil aerated, and it always has identical quadruplets.',
    facts: ['It jumps straight up when startled, which is why so many are hit by cars.', 'It can hold its breath for six minutes and walk across the bottom of a stream.', 'Grub control: an armadillo eats 40,000 insects a night, grubs first.'] },
  { id: 'llama', ride: true, name: 'Llama', sci: 'Lama glama', biomes: ['prairie', 'desert'], role: 'grazer', speed: 1.6,
    body: [0.45, 0.6, 1.0], legH: 0.75, head: [0.22, 0.26, 0.4], ears: true, colors: { body: '#e8dcc8', head: '#d8ccb8', legs: '#c8bca8', accent: '#8a6a4a' },
    teach: 'The Inca pack animal, bred from the wild guanaco 5,000 years ago. Llamas carried the terrace soil up to Machu Picchu, and their dung, dropped in communal piles, was the fertiliser that made maize grow at 3,500 m.',
    facts: ['Llama pellets are cool and odourless: usable on a garden fresh.', 'They guard sheep flocks and will chase a coyote off.', 'A llama hums to its herd and spits only at other llamas, usually.'] },
  { id: 'mallard', name: 'Mallard', sci: 'Anas platyrhynchos', biomes: ['wetland', 'temperate', 'prairie'], role: 'neutral', flies: true, speed: 2.2, scale: 0.45, aquaticOk: true,
    body: [0.22, 0.2, 0.42], legH: 0.1, head: [0.14, 0.14, 0.18], beak: true, colors: { body: '#8a7a6a', head: '#2a7a4a', legs: '#f0a030', accent: '#e8c030' },
    teach: 'Ducks are seed farmers: a mallard eats pondweed and sedge seed, flies to the next pond and plants it in a dropping. Studies find viable seeds of 30 plant species in a single duck.',
    facts: ['The drake\'s green head is iridescent: structural colour, no green pigment.', 'Ducklings eat insects for their first weeks and switch to plants.', 'A pond with ducks grows more kinds of water plants than one without.'] },
  { id: 'canada_goose', name: 'Canada Goose', sci: 'Branta canadensis', biomes: ['wetland', 'prairie', 'boreal', 'temperate'], role: 'herbivore', flies: true, speed: 2.0, scale: 0.6,
    body: [0.3, 0.28, 0.6], legH: 0.14, head: [0.14, 0.14, 0.2], beak: true, colors: { body: '#8a8070', head: '#1a1a1a', legs: '#2a2a2a', accent: '#f0f0f0' },
    teach: 'Geese are grazers, like tiny cattle: they crop lawns and winter wheat and leave a kilo of droppings a day each. The V formation saves each bird a quarter of its energy by riding the one ahead.',
    facts: ['A goose mates for life and defends its nest against anything, including you.', 'Parks with short mown lawns to the water\'s edge are goose heaven; a strip of tall plants keeps them off.', 'They navigate by stars, sun and the Earth\'s magnetic field.'] },
  { id: 'blue_jay', name: 'Blue Jay', sci: 'Cyanocitta cristata', biomes: ['temperate', 'prairie'], role: 'beneficial', flies: true, speed: 3, scale: 0.35, eats: ['tent_caterpillar', 'spongy_moth', 'grasshopper', 'cabbage_white'],
    body: [0.14, 0.14, 0.26], legH: 0, head: [0.11, 0.12, 0.12], beak: true, colors: { body: '#4a7ac8', head: '#5a8ad8', legs: '#2a2a2a', accent: '#1a1a1a' },
    teach: 'The blue jay planted the oak forests. After the ice age, oaks spread north faster than acorns can roll because jays carry acorns kilometres and bury thousands each autumn, forgetting enough to grow a woodland.',
    facts: ['A jay can carry five acorns at once: three in its throat, one in its mouth, one in its bill.', 'It is not blue: the feathers scatter light; crush one and it is brown.', 'Jays mimic hawks to scare other birds off a feeder.'] },
  { id: 'cardinal', name: 'Northern Cardinal', sci: 'Cardinalis cardinalis', biomes: ['temperate', 'prairie', 'desert'], role: 'neutral', flies: true, speed: 2.6, scale: 0.32,
    body: [0.12, 0.13, 0.24], legH: 0, head: [0.1, 0.11, 0.11], beak: true, colors: { body: '#d02020', head: '#e03030', legs: '#9a6a5a', accent: '#f0a030' },
    teach: 'The red comes from carotenoid pigments in the seeds and berries it eats: a cardinal on a poor diet fades. Its heavy bill cracks sunflower, safflower and dogwood seeds other birds cannot.',
    facts: ['Both sexes sing; the female sings from the nest to tell the male when to bring food.', 'Cardinals do not migrate, which is why they brighten winter feeders.', 'Dense shrubs (dogwood, elderberry, hawthorn) are where they nest.'] },
  { id: 'robin', name: 'American Robin', sci: 'Turdus migratorius', biomes: ['temperate', 'prairie', 'boreal'], role: 'beneficial', flies: true, speed: 2.6, scale: 0.33, eats: ['cutworm', 'wireworm', 'root_maggot', 'japanese_beetle'],
    body: [0.13, 0.13, 0.26], legH: 0, head: [0.1, 0.1, 0.11], beak: true, colors: { body: '#5a5a5a', head: '#3a3a3a', legs: '#4a3a2a', accent: '#e08030' },
    teach: 'The robin cocks its head to see a worm, not hear it. It eats 4 metres of earthworms a day in spring and switches to fruit in autumn, spreading dogwood, holly and juniper seed.',
    facts: ['Robins nest three times a summer; the sky-blue eggs gave a colour its name.', 'They hunt lawns after rain because worms surface to breathe.', 'Lawn pesticides poisoned so many robins in the 1950s that it helped start the environmental movement.'] },
  { id: 'bald_eagle', name: 'Bald Eagle', sci: 'Haliaeetus leucocephalus', biomes: ['wetland', 'boreal', 'temperate'], role: 'neutral', flies: true, speed: 3.4, scale: 0.9,
    body: [0.3, 0.3, 0.6], legH: 0.1, head: [0.18, 0.18, 0.22], beak: true, colors: { body: '#3a2a20', head: '#f4f4f4', legs: '#f0c030', accent: '#f0c030' },
    teach: 'DDT sprayed on crops washed into rivers, built up in fish, and thinned eagle eggshells until they broke under the sitting bird. There were 417 pairs left in 1963. DDT was banned in 1972; today there are over 70,000 pairs.',
    facts: ['An eagle nest is reused for decades and can weigh a tonne.', 'Eagles fish, scavenge and steal from ospreys.', 'The white head arrives at five years old.'] },
  { id: 'great_horned_owl', name: 'Great Horned Owl', sci: 'Bubo virginianus', biomes: ['temperate', 'boreal', 'desert', 'prairie'], role: 'beneficial', flies: true, speed: 2.4, scale: 0.6, eats: [],
    body: [0.26, 0.3, 0.4], legH: 0.06, head: [0.26, 0.24, 0.24], ears: true, beak: true, colors: { body: '#8a7a60', head: '#9a8a70', legs: '#c8b890', accent: '#f0c030' },
    teach: 'The farm\'s night rodent patrol: an owl family eats 3,000 mice, voles and rabbits a year. Its feathers are fringed so the flight is silent, and the ear tufts are not ears at all.',
    facts: ['Owls cannot move their eyes, so they turn their heads 270 degrees.', 'An owl box on a pole protects an orchard better than poison, which also kills the owls.', 'It is the only animal that regularly eats skunks: it has almost no sense of smell.'] },
  { id: 'red_tailed_hawk', name: 'Red-tailed Hawk', sci: 'Buteo jamaicensis', biomes: ['prairie', 'desert', 'temperate'], role: 'beneficial', flies: true, speed: 3.2, scale: 0.65, eats: [],
    body: [0.26, 0.26, 0.5], legH: 0.08, head: [0.16, 0.16, 0.2], beak: true, colors: { body: '#7a5a3a', head: '#6a4a2a', legs: '#f0c030', accent: '#c84a2a' },
    teach: 'The hawk on every fence post along the highway. It hunts rabbits, gophers and ground squirrels from a perch, and a hawk pair keeps a farm\'s rodents in check across a square mile.',
    facts: ['Its scream is the sound Hollywood gives every eagle.', 'The red tail comes at two years old.', 'Hawks ride thermals: rising warm air off sun-heated ground.'] },
  { id: 'sandhill_crane', name: 'Sandhill Crane', sci: 'Antigone canadensis', biomes: ['wetland', 'prairie', 'tundra'], role: 'herbivore', flies: true, speed: 1.6, scale: 0.9,
    body: [0.3, 0.4, 0.7], legH: 0.9, head: [0.14, 0.14, 0.3], beak: true, colors: { body: '#9a9a90', head: '#9a9a90', legs: '#3a3a3a', accent: '#d03030' },
    teach: 'Half a million cranes stop on the Platte River each March, the largest gathering of cranes on Earth, fattening on waste corn in the fields before flying to the Arctic. They dance: leaping, bowing, throwing sticks.',
    facts: ['Cranes paint their grey feathers with iron-rich mud for camouflage on the nest.', 'A fossil crane from Nebraska is 10 million years old: the oldest living bird species.', 'They eat tubers, grain, frogs and mice.'] },
  { id: 'woodpecker', name: 'Pileated Woodpecker', sci: 'Dryocopus pileatus', biomes: ['temperate', 'boreal'], role: 'beneficial', flies: true, speed: 2.4, scale: 0.5, eats: ['bark_beetle', 'emerald_ash_borer', 'codling_moth'],
    body: [0.16, 0.18, 0.4], legH: 0, head: [0.14, 0.16, 0.2], beak: true, colors: { body: '#1a1a1a', head: '#1a1a1a', legs: '#4a4a4a', accent: '#e02020' },
    teach: 'A crow-sized woodpecker that chisels rectangular holes into dead trees after carpenter ants and beetle grubs. Those holes become homes for owls, ducks, bats and flying squirrels: leave dead trees standing.',
    facts: ['Its skull has a spongy bone shock absorber and a tongue that wraps around the brain.', 'The drumming is a territorial song, not feeding.', 'Woodpeckers find emerald ash borer under the bark and eat 85% of the larvae in some trees.'] },
  { id: 'loon', name: 'Common Loon', sci: 'Gavia immer', biomes: ['boreal', 'tundra'], role: 'neutral', flies: true, speed: 2.2, scale: 0.6, aquaticOk: true,
    body: [0.26, 0.22, 0.6], legH: 0.04, head: [0.14, 0.14, 0.26], beak: true, colors: { body: '#1a1a1a', head: '#1a1a1a', legs: '#2a2a2a', accent: '#f0f0f0' },
    teach: 'The voice of the north woods lake. Loons need clear water to see fish, so they are the first to leave a lake clouded by algae from fertiliser runoff. Lead fishing sinkers are their biggest killer.',
    facts: ['Solid bones let it dive 60 m; it runs 400 m across the water to take off.', 'The chicks ride on the parents\' backs.', 'Each pair needs its own lake of at least 5 hectares.'] },
  { id: 'kingfisher', name: 'Belted Kingfisher', sci: 'Megaceryle alcyon', biomes: ['wetland', 'temperate', 'boreal'], role: 'neutral', flies: true, speed: 3, scale: 0.4,
    body: [0.14, 0.15, 0.28], legH: 0, head: [0.14, 0.14, 0.16], beak: true, colors: { body: '#4a7a9a', head: '#3a6a8a', legs: '#2a2a2a', accent: '#1a1a1a' },
    teach: 'It rattles along the stream, hovers, and plunges head-first for minnows. Kingfishers nest in a tunnel dug 2 m into a sandy bank, which is why streams with straightened, armoured banks lose them.',
    facts: ['The female is more colourful than the male, rare among birds.', 'It beats a fish on a branch before swallowing it head first.', 'Clear water and natural banks: a kingfisher is a stream health report.'] },
  { id: 'pelican', name: 'American White Pelican', sci: 'Pelecanus erythrorhynchos', biomes: ['wetland', 'prairie'], role: 'neutral', flies: true, speed: 2.0, scale: 1.0, aquaticOk: true,
    body: [0.4, 0.4, 0.9], legH: 0.14, head: [0.2, 0.2, 0.3], beak: true, colors: { body: '#f4f0e8', head: '#f4f0e8', legs: '#f0a030', accent: '#f0a030' },
    teach: 'A 3-metre wingspan and a bill pouch that holds 11 litres. White pelicans do not dive; a flock swims in a line and herds fish into the shallows together. They breed on islands in prairie lakes and fly 150 km to fish.',
    facts: ['A pelican eats 2 kg of fish a day, mostly carp and minnows nobody wants.', 'DDT nearly ended them too; they recovered after the ban.', 'Thermals carry flocks so high they vanish from sight.'] },
  { id: 'largemouth_bass', name: 'Largemouth Bass', sci: 'Micropterus salmoides', biomes: ['wetland', 'temperate', 'prairie'], role: 'neutral', aquatic: true, speed: 1.8, scale: 0.55,
    body: [0.12, 0.26, 0.5], legH: 0, head: [0.1, 0.2, 0.16], colors: { body: '#4a6a3a', head: '#3a5a2a', legs: '#2a2a2a', accent: '#d8d8b0' },
    teach: 'The top predator of a warm pond. Bass keep bluegill numbers down so the survivors grow large; a pond without bass fills with stunted fish. They ambush from weed beds, so pondweed matters to the fishing.',
    facts: ['A bass can swallow prey half its own length.', 'Males guard the nest and fry for weeks.', 'The most popular game fish in America and introduced, often harmfully, on every continent but Antarctica.'] },
  { id: 'salmon', name: 'Sockeye Salmon', sci: 'Oncorhynchus nerka', biomes: ['boreal'], role: 'neutral', aquatic: true, speed: 2.4, scale: 0.6,
    body: [0.12, 0.26, 0.6], legH: 0, head: [0.1, 0.2, 0.2], colors: { body: '#d03030', head: '#4a8a4a', legs: '#2a2a2a', accent: '#f0f0f0' },
    teach: 'Salmon carry the ocean into the forest. Bears and eagles drag the spawned-out fish onto the banks, and streamside trees get up to a quarter of their nitrogen from salmon. Rings in old spruce record good salmon years.',
    facts: ['A sockeye swims 1,500 km upstream and climbs 2,000 m to the lake where it hatched, by smell.', 'The red colour is carotenoid pigment from the krill it ate at sea.', 'Dams, warm water and silt from logging are why most runs are a tenth of what they were.'] },
  { id: 'sea_turtle', name: 'Green Sea Turtle', sci: 'Chelonia mydas', biomes: ['wetland', 'rainforest'], role: 'herbivore', aquatic: true, speed: 1.2, scale: 1.0,
    body: [0.6, 0.25, 0.8], legH: 0.06, head: [0.2, 0.16, 0.28], colors: { body: '#5a7a4a', head: '#7a8a6a', legs: '#6a7a5a', accent: '#c8b878' },
    teach: 'The only sea turtle that grazes: it mows seagrass meadows, which keeps them young and growing, and the meadows store carbon faster than rainforest. It returns to lay eggs on the beach where it hatched, decades later.',
    facts: ['A hatchling\'s sex is set by nest temperature; warming beaches are producing almost all females.', 'Green turtles can live 80 years and weigh 180 kg.', 'Lights on a beach lead hatchlings inland instead of to the sea.'] },
  { id: 'manatee', name: 'West Indian Manatee', sci: 'Trichechus manatus', biomes: ['wetland'], role: 'herbivore', aquatic: true, speed: 0.9, scale: 1.2,
    body: [0.6, 0.5, 1.4], legH: 0, head: [0.3, 0.3, 0.4], colors: { body: '#8a8a88', head: '#9a9a98', legs: '#7a7a78', accent: '#6a6a68' },
    teach: 'A sea cow: 500 kg of gentle grazer eating 50 kg of seagrass and water hyacinth a day. Florida\'s manatees starve when fertiliser runoff clouds the water and kills the seagrass, as it did in 2021.',
    facts: ['Its closest relative is the elephant.', 'Manatees cannot survive water below 20 °C and gather at warm springs in winter.', 'Boat propellers scar most adults; slow zones are their main protection.'] },
  { id: 'snapping_turtle', name: 'Common Snapping Turtle', sci: 'Chelydra serpentina', biomes: ['wetland', 'temperate'], role: 'neutral', speed: 0.6, scale: 0.6, aquaticOk: true,
    body: [0.4, 0.2, 0.5], legH: 0.1, head: [0.18, 0.14, 0.26], colors: { body: '#4a4a3a', head: '#5a5a4a', legs: '#4a4a3a', accent: '#3a3a2a' },
    teach: 'The pond\'s garbage collector: it eats dead fish, frogs, water plants and the occasional duckling, and it has been doing so since before the dinosaurs ended. On land in June the female is looking for sandy soil to lay in. Do not help her by the tail.',
    facts: ['It cannot pull into its shell, so it bites instead.', 'Eggs take three months to hatch and raccoons dig up most nests.', 'A snapper can live 100 years.'] },
  { id: 'muskrat', name: 'Muskrat', sci: 'Ondatra zibethicus', biomes: ['wetland', 'prairie'], role: 'herbivore', speed: 1.2, scale: 0.45, aquaticOk: true,
    body: [0.22, 0.2, 0.4], legH: 0.08, head: [0.14, 0.12, 0.18], colors: { body: '#5a3a2a', head: '#5a3a2a', legs: '#3a2a1a', accent: '#2a1a10' },
    teach: 'It builds domed lodges of cattail and eats the roots. A marsh with the right number of muskrats has open water between the reeds where ducks and fish live; too few and cattails choke the pond, too many and it is bare.',
    facts: ['The flattened tail is a rudder; it swims backwards as well as forwards.', 'Muskrat lodges are winter perches for geese and nesting platforms for terns.', 'Trappers once took 10 million a year for fur.'] },
  { id: 'crayfish', name: 'Crayfish', sci: 'Faxonius virilis', biomes: ['wetland', 'temperate', 'prairie'], role: 'neutral', aquatic: true, speed: 0.8, scale: 0.35,
    body: [0.14, 0.1, 0.36], legH: 0.04, head: [0.1, 0.08, 0.1], colors: { body: '#8a4a2a', head: '#7a3a1a', legs: '#6a3a1a', accent: '#9a5a3a' },
    teach: 'Freshwater lobsters that shred dead leaves into the fine particles the whole stream food web eats. Their burrows, the mud chimneys in a wet meadow, aerate the soil and reach the water table.',
    facts: ['Crayfish moult to grow and eat the old shell for the calcium.', 'Frogs, herons, otters, bass and people all eat them.', 'Bait-bucket crayfish released into new lakes have become invasive across the continent.'] },
  { id: 'salamander', name: 'Spotted Salamander', sci: 'Ambystoma maculatum', biomes: ['temperate'], role: 'beneficial', speed: 0.7, scale: 0.4, eats: ['slug', 'cutworm', 'root_maggot'],
    body: [0.1, 0.08, 0.4], legH: 0.05, head: [0.09, 0.07, 0.1], colors: { body: '#2a2a3a', head: '#2a2a3a', legs: '#2a2a3a', accent: '#f0d040' },
    teach: 'On the first warm rainy night of spring, thousands cross roads to breed in woodland pools that dry up by summer, so no fish eat the eggs. The rest of the year they live under logs, eating slugs and beetle grubs. The eggs host a green alga inside the embryo: a solar-powered salamander.',
    facts: ['They can live 30 years under the same log.', 'Vernal pools, the temporary woodland ponds, are the whole reason they exist; fill one and the forest loses its salamanders.', 'Towns close roads on migration night.'] },
  // ---- tundra ----
  { id: 'musk_ox', name: 'Muskox', sci: 'Ovibos moschatus', biomes: ['tundra'], role: 'grazer', ride: true, speed: 1.4, body: [0.8, 0.85, 1.4], legH: 0.5, head: [0.42, 0.42, 0.5], colors: { body: '#3a2e24', head: '#2e241c', legs: '#d8d0c0', accent: '#c8bca8' },
    teach: 'An Ice Age survivor that grazed beside mammoths and is still here, wearing the warmest wool in the world: qiviut, eight times warmer than sheep wool and finer than cashmere, shed in sheets each spring. Faced with wolves the herd forms a ring, horns out, calves in the middle.',
    facts: ['Not an ox but a giant goat-antelope; its nearest relative is the takin of Tibet.', 'It digs through snow with its hooves to reach willow and sedge all winter, never migrating.', 'Hunted out of Alaska by 1900 and brought back from Greenland in 1930; 5,000 live there now.'] },
  { id: 'arctic_fox', name: 'Arctic Fox', sci: 'Vulpes lagopus', biomes: ['tundra'], role: 'neutral', speed: 2.4, scale: 0.6, body: [0.26, 0.3, 0.55], legH: 0.22, head: [0.18, 0.18, 0.24], colors: { body: '#f0f2f4', head: '#e8ecf0', legs: '#dcdfe4', accent: '#f4f4f4' },
    teach: 'White in winter, brown in summer, with fur on the soles of its feet and the warmest coat of any mammal: it does not start to shiver until minus 70 °C. It follows polar bears for scraps, caches lemmings and goose eggs for winter, and can hear a lemming running under a metre of snow.',
    facts: ['A litter can be 14 kits in a lemming year, the biggest of any wild dog.', 'Its dens are used for centuries and grow so fertile that they show as green patches on the tundra.', 'It has walked across sea ice from Norway to Canada: 3,500 km in 76 days.'] },
  { id: 'arctic_hare', name: 'Arctic Hare', sci: 'Lepus arcticus', biomes: ['tundra'], role: 'herbivore', speed: 2.8, scale: 0.55, body: [0.3, 0.3, 0.55], legH: 0.18, head: [0.18, 0.18, 0.22], colors: { body: '#f2f4f6', head: '#eef0f2', legs: '#e0e2e6', accent: '#1a1a1a' },
    teach: 'A hare the size of a small dog, white all year in the far north, that sits hunched like a stone to hide its heat. It runs at 60 km/h, sometimes hopping on its hind legs like a kangaroo, and digs willow and saxifrage out from under the snow with claws built for it.',
    facts: ['In the high Arctic they gather in groups of hundreds for warmth and many eyes.', 'Leverets are born furred with eyes open and are left alone in the open from day one.', 'Black ear tips are the one patch of colour: they show up to other hares but not to a flying owl.'] },
  { id: 'lemming', name: 'Brown Lemming', sci: 'Lemmus trimucronatus', biomes: ['tundra'], role: 'herbivore', speed: 1.6, scale: 0.28, body: [0.16, 0.14, 0.24], legH: 0.05, head: [0.12, 0.11, 0.12], colors: { body: '#8a6a3a', head: '#7a5a30', legs: '#5a4a3a', accent: '#c8a870' },
    teach: 'The engine of the tundra. A fat rodent that breeds all winter under the snow, eating moss and sedge, and every three or four years the numbers explode to hundreds per hectare. Owls, foxes, weasels, skuas and gulls all feast; the next year the lemmings crash and so do they.',
    facts: ['They do not jump off cliffs; that myth was staged for a 1958 film.', 'Under the snow they live in a warm layer called the subnivean space, at 0 °C while the air is minus 40.', 'A female can have her first litter at three weeks old.'] },
  { id: 'polar_bear', ride: true, name: 'Polar Bear', sci: 'Ursus maritimus', biomes: ['tundra'], role: 'neutral', noLeash: true, speed: 1.9, body: [0.7, 0.75, 1.5], legH: 0.5, head: [0.32, 0.3, 0.45], colors: { body: '#f0ece0', head: '#ece8dc', legs: '#e4e0d4', accent: '#1a1a1a' },
    teach: 'The largest land carnivore, a bear that became a sea animal: it hunts seals from the ice, swims for days, and its hollow guard hairs and black skin soak up the sun. It is tied to sea ice; where the ice season shortens, bears come ashore hungry and that is why it is the face of a warming Arctic.',
    facts: ['Its fur is not white but clear; it only looks white, like snow.', 'A bear can smell a seal through a metre of ice from a kilometre away.', 'Mothers den in snow for the winter and nurse cubs for months without eating.'] },
  { id: 'arctic_char', name: 'Arctic Char', sci: 'Salvelinus alpinus', biomes: ['tundra', 'boreal'], role: 'neutral', aquatic: true, speed: 1.7, scale: 0.5, body: [0.09, 0.22, 0.36], legH: 0, head: [0.08, 0.15, 0.1], colors: { body: '#4a6a7a', head: '#3a5a6a', legs: '#2a2a2a', accent: '#e86a3a' },
    teach: 'The fish that lives farther north than any other freshwater fish, in lakes that are iced over ten months a year. Some run to the sea each summer and come back orange-bellied to spawn; others never leave a single lake, and in some lakes one species has split into dwarf and giant forms that no longer breed together.',
    facts: ['It is a relic of the ice age, left behind in mountain lakes as far south as the Alps.', 'Char means red in Gaelic, for the spawning male\'s belly.', 'In Arctic Canada it is the main food of whole communities, netted under the ice.'] },
  { id: 'snowy_owl', name: 'Snowy Owl', sci: 'Bubo scandiacus', biomes: ['tundra', 'prairie'], role: 'beneficial', flies: true, speed: 3, scale: 0.6, body: [0.26, 0.28, 0.5], legH: 0.1, head: [0.2, 0.2, 0.22], beak: true, colors: { body: '#f4f4f0', head: '#f8f8f4', legs: '#e8e8e0', accent: '#2a2a2a' },
    teach: 'A ground-nesting owl that hunts by day in the endless Arctic summer. The number of eggs it lays follows the lemmings: eleven in a boom year, none in a bust. In winters when the young are many it flies south and turns up on prairie fence posts and airport runways.',
    facts: ['Feathered to the toes, it is the heaviest owl in North America.', 'A snowy owl eats 1,600 lemmings a year.', 'Males grow whiter with age; females keep dark bars all their lives.'] },
  { id: 'rock_ptarmigan', name: 'Rock Ptarmigan', sci: 'Lagopus muta', biomes: ['tundra'], role: 'herbivore', flies: false, speed: 1.3, scale: 0.4, body: [0.22, 0.22, 0.34], legH: 0.1, head: [0.12, 0.12, 0.14], beak: true, colors: { body: '#f0f0ec', head: '#e8e6e0', legs: '#f4f4f0', accent: '#c82a2a' },
    teach: 'A grouse that changes clothes three times a year: pure white in winter, mottled brown in summer, grey in autumn, always matching the ground. Its feet are feathered into snowshoes and it spends winter nights buried in snow drifts, eating willow buds.',
    facts: ['The p in ptarmigan is silent; an 18th-century scholar added it to make the Gaelic word look Greek.', 'It is the only bird that lives year-round in the high Arctic.', 'Males keep their white plumage into spring on purpose, to show off, and dirty it with mud once mated.'] },
  { id: 'snow_bunting', name: 'Snow Bunting', sci: 'Plectrophenax nivalis', biomes: ['tundra'], role: 'beneficial', flies: true, speed: 3.2, scale: 0.3, body: [0.12, 0.12, 0.22], legH: 0, head: [0.1, 0.1, 0.11], beak: true, colors: { body: '#f4f4f4', head: '#f8f8f8', legs: '#1a1a1a', accent: '#2a2a2a' },
    teach: 'The songbird that nests farthest north of any on Earth, in rock crevices on the tundra and on Greenland cliffs, lining the nest with ptarmigan feathers. The male arrives in April to minus 30 °C to claim a crack in the rocks, weeks before any insect flies.',
    facts: ['Flocks in winter look like blowing snow, which earned them the name snowflake.', 'The female cannot leave the eggs in the cold, so the male feeds her on the nest.', 'They eat seeds in winter and switch to insects to feed chicks, like most songbirds.'] },
  { id: 'arctic_tern', name: 'Arctic Tern', sci: 'Sterna paradisaea', biomes: ['tundra', 'wetland'], role: 'neutral', flies: true, speed: 3.8, scale: 0.4, body: [0.12, 0.12, 0.3], legH: 0, head: [0.1, 0.1, 0.14], beak: true, colors: { body: '#eef0f2', head: '#1a1a1a', legs: '#d83a2a', accent: '#d83a2a' },
    teach: 'The longest migration of any animal: it breeds in the Arctic summer and flies to the Antarctic for the southern summer, 70,000 km a year, so it sees more daylight than any creature alive. It nests on open gravel and dive-bombs anything that comes near, which is why other birds nest beside it for protection.',
    facts: ['A tern ringed in Britain in 1982 was still breeding in 2012, having flown about 3 million km.', 'It hovers, then plunges for small fish; it does not swim.', 'Its red bill and feet are the only colour on it.'] },
  { id: 'gyrfalcon', name: 'Gyrfalcon', sci: 'Falco rusticolus', biomes: ['tundra'], role: 'beneficial', flies: true, speed: 4.2, scale: 0.55, body: [0.2, 0.22, 0.48], legH: 0.08, head: [0.14, 0.14, 0.18], beak: true, colors: { body: '#d8dce0', head: '#c8ccd2', legs: '#f0c030', accent: '#4a4a4a' },
    teach: 'The largest falcon in the world and the bird of kings: medieval law reserved it for royalty. It chases ptarmigan low across the tundra in a straight power flight rather than a stoop, and nests on cliff ledges that falcons have used for 2,500 years, the guano dated by scientists.',
    facts: ['It comes in white, grey and nearly black; the white ones live farthest north.', 'Some gyrfalcons spend the winter out on the sea ice, resting on icebergs.', 'Ptarmigan make up most of its diet, so its numbers follow theirs.'] },
  { id: 'common_raven', name: 'Common Raven', sci: 'Corvus corax', biomes: ['tundra', 'boreal', 'desert', 'prairie'], role: 'neutral', flies: true, speed: 3.2, scale: 0.5, body: [0.2, 0.2, 0.48], legH: 0.06, head: [0.14, 0.14, 0.2], beak: true, colors: { body: '#1a1a1e', head: '#141418', legs: '#1a1a1a', accent: '#2a2a30' },
    teach: 'The cleverest bird on the tundra and nearly everywhere else: it solves puzzles, plans ahead, plays in the wind and calls wolves to a carcass it cannot open itself. Ravens live from the Arctic to the Sonoran desert because they will eat anything and remember everything.',
    facts: ['A raven can recognise individual human faces for years.', 'Pairs mate for life and perform tumbling, rolling flights together.', 'It is the largest songbird, with a 1.3 m wingspan.'] },
  // ---- boreal birds ----
  { id: 'canada_jay', name: 'Canada Jay', sci: 'Perisoreus canadensis', biomes: ['boreal'], role: 'beneficial', flies: true, speed: 2.8, scale: 0.35, body: [0.14, 0.14, 0.28], legH: 0, head: [0.12, 0.12, 0.13], beak: true, colors: { body: '#8a9098', head: '#f0f0f0', legs: '#2a2a2a', accent: '#3a3a40' },
    teach: 'The whiskey jack, the fearless grey bird that lands on your hand in a spruce forest. It nests in February at minus 30 °C because it has spent all summer gluing food into thousands of bark crevices with its sticky saliva, enough to raise chicks before anything thaws.',
    facts: ['It remembers thousands of cache sites; warm autumns that rot the stored food are shrinking its range.', 'Named Canada\'s national bird by popular vote in 2016.', 'Young birds fight until one stays with the parents and the rest are driven off.'] },
  { id: 'spruce_grouse', name: 'Spruce Grouse', sci: 'Canachites canadensis', biomes: ['boreal'], role: 'herbivore', flies: false, speed: 1.2, scale: 0.45, body: [0.24, 0.24, 0.38], legH: 0.1, head: [0.13, 0.13, 0.15], beak: true, colors: { body: '#3a3a36', head: '#2a2a28', legs: '#6a5a4a', accent: '#d82a2a' },
    teach: 'The fool hen: so trusting it can be caught by hand. It lives all winter on spruce and pine needles, which almost nothing else can digest; its gut grows longer in autumn to cope, and it swallows grit to grind them.',
    facts: ['Males display with a red comb over each eye and a drumming wing-flutter.', 'It spends winter nights buried in snow, which is warmer than the air by 20 degrees.', 'Needle-eating gives the meat a resinous taste that trappers call turpentine.'] },
  { id: 'bohemian_waxwing', name: 'Bohemian Waxwing', sci: 'Bombycilla garrulus', biomes: ['boreal', 'temperate'], role: 'beneficial', flies: true, speed: 3.4, scale: 0.32, body: [0.13, 0.13, 0.24], legH: 0, head: [0.11, 0.11, 0.12], beak: true, colors: { body: '#b89a80', head: '#c8a888', legs: '#1a1a1a', accent: '#d82a2a' },
    teach: 'A sleek crested bird with waxy red tips on its wings that lives almost entirely on berries: rowan, juniper, crabapple. Flocks of hundreds strip a tree in minutes and move on, spreading the seeds across the forest. In winter they wander south in irruptions wherever the berry crop failed.',
    facts: ['They can get drunk on fermented berries in late winter.', 'The red wing tips are flattened feather shafts, like sealing wax.', 'A waxwing eats several times its weight in berries a day and passes the seeds in 20 minutes.'] },
  // ---- prairie birds ----
  { id: 'western_meadowlark', name: 'Western Meadowlark', sci: 'Sturnella neglecta', biomes: ['prairie'], role: 'beneficial', flies: true, speed: 2.8, scale: 0.34, body: [0.14, 0.14, 0.26], legH: 0.04, head: [0.11, 0.11, 0.13], beak: true, colors: { body: '#a08a5a', head: '#8a7a4a', legs: '#9a8a6a', accent: '#f0d020' },
    teach: 'The voice of the prairie, a flute song from a fence post with a bright yellow breast and a black V. It walks through the grass eating grasshoppers and beetles and builds a domed grass nest on the ground with a side tunnel. Six states have made it their state bird.',
    facts: ['Eastern and western meadowlarks look alike; only the song tells them apart, and they do not interbreed.', 'Mowing hay in June destroys most nests; later cutting saves them.', 'In winter they switch to waste grain and weed seeds.'] },
  { id: 'burrowing_owl', name: 'Burrowing Owl', sci: 'Athene cunicularia', biomes: ['prairie', 'desert'], role: 'beneficial', flies: true, speed: 2.6, scale: 0.35, body: [0.14, 0.16, 0.26], legH: 0.14, head: [0.12, 0.12, 0.13], beak: true, colors: { body: '#a08060', head: '#9a7a5a', legs: '#c8b090', accent: '#f0d020' },
    teach: 'A long-legged owl that lives underground in old prairie dog and tortoise burrows, hunts by day, and lines its doorway with cow dung to lure the dung beetles it eats. When cornered in the burrow the chicks hiss exactly like a rattlesnake.',
    facts: ['Prairie dog poisoning takes its homes too; it is declining across the plains.', 'It bobs up and down when alarmed, which earned it the name howdy owl.', 'Pairs nest in loose colonies and share lookout duty.'] },
  { id: 'prairie_chicken', name: 'Greater Prairie-Chicken', sci: 'Tympanuchus cupido', biomes: ['prairie'], role: 'herbivore', flies: false, speed: 1.4, scale: 0.45, body: [0.24, 0.24, 0.38], legH: 0.12, head: [0.13, 0.13, 0.15], beak: true, colors: { body: '#a08a5a', head: '#8a7a4a', legs: '#9a8a6a', accent: '#f0a020' },
    teach: 'At dawn in April the males gather on a lek, a bare patch of prairie used for generations, stamp their feet, inflate orange air sacs on their necks and boom a sound that carries a mile. The hens choose the best dancer. The bird needs big unbroken grassland, which is why it is gone from most of its range.',
    facts: ['The booming ground is passed down; some have been used for a century.', 'Its eastern cousin, the heath hen, went extinct in 1932.', 'It survives winter by eating buds and burrowing into snow.'] },
  { id: 'barn_owl', name: 'Barn Owl', sci: 'Tyto alba', biomes: ['prairie', 'temperate', 'desert'], role: 'beneficial', flies: true, speed: 3, scale: 0.45, body: [0.18, 0.2, 0.4], legH: 0.1, head: [0.16, 0.16, 0.16], beak: true, colors: { body: '#d8b888', head: '#f4f0e8', legs: '#e8dcc8', accent: '#1a1a1a' },
    teach: 'The heart-faced owl found on every continent but Antarctica, hunting mice over fields in silence: comb-edged feathers muffle its wings and its lopsided ears pinpoint a mouse in total darkness. One family eats 3,000 rodents a year, which is why farmers put up barn owl boxes instead of poison.',
    facts: ['It does not hoot; it screeches, which gave old barns their ghosts.', 'The facial disc works as a dish that funnels sound to the ears.', 'Rat poison kills owls that eat poisoned rats; it is the main threat to them.'] },
  // ---- desert birds ----
  { id: 'gambels_quail', name: 'Gambel\'s Quail', sci: 'Callipepla gambelii', biomes: ['desert'], role: 'herbivore', flies: false, speed: 1.8, scale: 0.35, body: [0.18, 0.18, 0.28], legH: 0.1, head: [0.11, 0.11, 0.12], beak: true, colors: { body: '#8a8a8a', head: '#5a3a2a', legs: '#6a6a6a', accent: '#1a1a1a' },
    teach: 'The topknot quail of the Sonoran desert, running in coveys of twenty under the mesquite with a black plume bobbing over its forehead. It drinks dew and gets most of its water from green shoots, and a wet winter means a huge spring hatch; a dry one and few even try.',
    facts: ['Chicks leave the nest hours after hatching and follow the parents in a line.', 'The plume is actually six overlapping feathers.', 'Coveys roost together in a shrub, tails inward, facing out for danger.'] },
  { id: 'cactus_wren', name: 'Cactus Wren', sci: 'Campylorhynchus brunneicapillus', biomes: ['desert'], role: 'beneficial', flies: true, speed: 2.6, scale: 0.32, body: [0.13, 0.13, 0.25], legH: 0.03, head: [0.1, 0.1, 0.12], beak: true, colors: { body: '#9a7a5a', head: '#6a4a3a', legs: '#5a4a3a', accent: '#f4ecdc' },
    teach: 'The largest wren in North America builds football-shaped nests deep in the arms of a cholla, where the spines keep snakes and hawks out. It builds several and sleeps in the spares all year. Its chugging song is the sound of the Sonoran desert at noon.',
    facts: ['Arizona\'s state bird.', 'It rarely drinks, taking its water from insects and cactus fruit.', 'The nest entrance faces away from the cold spring wind and toward the summer breeze.'] },
  { id: 'turkey_vulture', name: 'Turkey Vulture', sci: 'Cathartes aura', biomes: ['desert', 'prairie', 'temperate'], role: 'neutral', flies: true, speed: 3, scale: 0.85, body: [0.28, 0.28, 0.6], legH: 0.1, head: [0.14, 0.14, 0.18], beak: true, colors: { body: '#2a2422', head: '#c8403a', legs: '#d8c8b8', accent: '#8a8a90' },
    teach: 'The desert\'s clean-up crew, rocking on raised wings on the warm air and finding carcasses by smell, which almost no other bird can do. Its stomach acid destroys anthrax, cholera and botulism, so a vulture removes disease from the land rather than spreading it.',
    facts: ['The bare red head stays clean when it feeds inside a carcass.', 'It cools itself by squirting on its own legs.', 'Gas companies once found pipeline leaks by watching where vultures gathered: the odorant smells like rot.'] },
  // ---- wetland birds ----
  { id: 'red_winged_blackbird', name: 'Red-winged Blackbird', sci: 'Agelaius phoeniceus', biomes: ['wetland', 'prairie'], role: 'beneficial', flies: true, speed: 3, scale: 0.32, body: [0.13, 0.13, 0.25], legH: 0.02, head: [0.1, 0.1, 0.12], beak: true, colors: { body: '#1a1a1a', head: '#141414', legs: '#2a2a2a', accent: '#e82a2a' },
    teach: 'The most abundant bird in North America, the male flashing scarlet shoulders from every cattail in the marsh. One male may hold a territory with fifteen females; he spends the spring singing and chasing off crows, herons and people who walk too close.',
    facts: ['The red patches can be hidden; a male on another\'s territory covers them to avoid a fight.', 'Winter flocks in the south can number millions.', 'It eats insects in summer and grain in autumn, which farmers resent.'] },
  { id: 'wood_duck', name: 'Wood Duck', sci: 'Aix sponsa', biomes: ['wetland', 'temperate'], role: 'neutral', flies: true, speed: 3, scale: 0.4, body: [0.2, 0.18, 0.36], legH: 0.06, head: [0.13, 0.13, 0.15], beak: true, colors: { body: '#6a4a3a', head: '#2a6a4a', legs: '#e8c050', accent: '#f4f0e8' },
    teach: 'The most beautiful duck in North America nests in tree holes above swamps, and a day after hatching the ducklings jump out, up to 15 metres, bounce, and follow their mother to the water. Hunted nearly to extinction by 1900, it recovered because people put up thousands of nest boxes.',
    facts: ['It has claws on its feet for perching in trees, unlike most ducks.', 'It eats acorns whole, with a gizzard strong enough to grind them.', 'Females lay eggs in each other\'s nests, so one box may hold 30 eggs.'] },
  { id: 'great_egret', name: 'Great Egret', sci: 'Ardea alba', biomes: ['wetland'], role: 'neutral', flies: true, speed: 2.8, scale: 0.8, body: [0.22, 0.26, 0.5], legH: 0.6, head: [0.12, 0.12, 0.3], beak: true, colors: { body: '#f8f8f6', head: '#f4f4f2', legs: '#1a1a1a', accent: '#f0c030' },
    teach: 'The tall white heron of the marsh, standing still until a fish comes within reach of its yellow dagger. Its lacy breeding plumes sold for more than gold in 1900 and 95 percent of the birds were shot for hats; the outrage founded the Audubon Society and the first bird protection laws.',
    facts: ['It is the symbol of the National Audubon Society.', 'Chicks fight in the nest and the strongest often kills the weakest.', 'It nests in colonies with herons, ibises and spoonbills, in trees over water for safety from raccoons.'] },
  { id: 'roseate_spoonbill', name: 'Roseate Spoonbill', sci: 'Platalea ajaja', biomes: ['wetland'], role: 'neutral', flies: true, speed: 2.6, scale: 0.7, body: [0.22, 0.24, 0.48], legH: 0.5, head: [0.12, 0.12, 0.3], beak: true, colors: { body: '#f0a0b8', head: '#e8e0d0', legs: '#d8506a', accent: '#c87a7a' },
    teach: 'A pink wading bird with a bill like a spatula that it sweeps side to side through muddy water, snapping shut on anything that touches it. Like a flamingo it is pink because of the pigments in the shrimp it eats; in a zoo on the wrong diet it fades to white.',
    facts: ['It is the only spoonbill in the Americas.', 'Nearly wiped out by plume hunters; Florida had 15 pairs in 1939.', 'The bald green head of an adult looks odd and makes it easy to tell from a flamingo.'] },
  // ---- rainforest birds ----
  { id: 'harpy_eagle', name: 'Harpy Eagle', sci: 'Harpia harpyja', biomes: ['rainforest'], role: 'neutral', flies: true, speed: 3.2, scale: 1.0, body: [0.32, 0.34, 0.6], legH: 0.14, head: [0.2, 0.22, 0.22], beak: true, colors: { body: '#3a3a40', head: '#c8c8c8', legs: '#f0d060', accent: '#f4f4f4' },
    teach: 'The most powerful eagle on Earth, with talons the size of a grizzly\'s claws, hunting sloths and monkeys from under the rainforest canopy. It needs huge tracts of unbroken forest and one nest tree, usually a kapok, so when the forest is cut into pieces the harpy is the first to vanish.',
    facts: ['A pair raises one chick every two or three years.', 'Its crest of grey feathers rises when it is alert.', 'Panama\'s national bird; the model for Fawkes in the Harry Potter films was a phoenix, but Buckbeak\'s face owes something to a harpy.'] },
  { id: 'quetzal', name: 'Resplendent Quetzal', sci: 'Pharomachrus mocinno', biomes: ['rainforest'], role: 'neutral', flies: true, speed: 2.8, scale: 0.4, body: [0.14, 0.14, 0.3], legH: 0, head: [0.11, 0.11, 0.13], beak: true, colors: { body: '#1a9a5a', head: '#2ab070', legs: '#4a4a4a', accent: '#e82a3a' },
    teach: 'The sacred bird of the Maya and Aztecs, emerald green with a scarlet breast and a tail a metre long; its feathers were worth more than gold and killing one was a capital crime. It lives on wild avocados in the cloud forest, swallowing the fruit whole and spitting out the stones, planting the forest as it goes.',
    facts: ['Guatemala\'s currency is called the quetzal.', 'It nests in a hole in a rotten trunk, the male\'s tail hanging out of the entrance.', 'The green is not pigment but light scattered by feather structure.'] },
  { id: 'hoatzin', name: 'Hoatzin', sci: 'Opisthocomus hoazin', biomes: ['rainforest', 'wetland'], role: 'herbivore', flies: true, speed: 1.6, scale: 0.5, body: [0.22, 0.24, 0.4], legH: 0.1, head: [0.12, 0.14, 0.14], beak: true, colors: { body: '#6a4a3a', head: '#3a7aa0', legs: '#4a4a4a', accent: '#d8a040' },
    teach: 'The stinkbird of Amazon riversides, the only bird that digests leaves by fermenting them in its crop like a cow. It smells of manure, flies badly, and its chicks are born with claws on their wings and climb like lizards, dropping into the river to escape snakes and climbing back out.',
    facts: ['Its nearest relatives are a mystery; it may be the last of a line 64 million years old.', 'The fermenting crop is so big the breastbone is shrunk, which is why it flies so badly.', 'Nobody hunts it: the meat tastes the way the bird smells.'] },
  // ---- temperate birds ----
  { id: 'barred_owl', name: 'Barred Owl', sci: 'Strix varia', biomes: ['temperate', 'wetland'], role: 'beneficial', flies: true, speed: 2.8, scale: 0.5, body: [0.22, 0.24, 0.42], legH: 0.1, head: [0.18, 0.18, 0.18], beak: true, colors: { body: '#8a7a6a', head: '#9a8a7a', legs: '#c8b8a0', accent: '#1a1a1a' },
    teach: 'The owl that asks who cooks for you from the swamp woods at dusk. Dark-eyed and round-headed, it hunts mice, frogs and crayfish from a low perch and nests in big hollow trees, which is why it needs old forest. It has spread west along planted trees across the plains and now crowds the spotted owl out of the Pacific forests.',
    facts: ['The only eastern owl with brown eyes; the rest have yellow.', 'Pairs duet in a raucous cackling that sounds like monkeys.', 'It will wade into shallow water to catch fish.'] },
  { id: 'eastern_bluebird', name: 'Eastern Bluebird', sci: 'Sialia sialis', biomes: ['temperate', 'prairie'], role: 'beneficial', flies: true, speed: 3, scale: 0.3, body: [0.12, 0.12, 0.22], legH: 0, head: [0.1, 0.1, 0.11], beak: true, colors: { body: '#3a6ac8', head: '#4a7ad8', legs: '#1a1a1a', accent: '#d86a3a' },
    teach: 'The bluebird of happiness nests in tree holes in open country and nearly disappeared when starlings and house sparrows took the holes and dead trees were cleared. Thousands of volunteers put up bluebird trails of nest boxes from the 1970s and the bird came back; it is the great success story of backyard conservation.',
    facts: ['It drops from a perch onto grasshoppers and beetles, then returns to the same perch.', 'Pairs raise two or three broods a summer; older chicks help feed the next brood.', 'The blue is structural; a feather in your hand against the light looks grey.'] },
  // ---- the player's own enchanted horse ----
  { id: 'enchanted_horse', name: 'Enchanted Horse', sci: 'Equus ferus caballus, with something extra', biomes: [], hidden: true, role: 'grazer', ride: true, speed: 8, body: [0.55, 0.7, 1.4], legH: 0.85, head: [0.3, 0.4, 0.55], colors: { body: '#f4f6fa', head: '#ecf0f6', legs: '#dfe4ee', accent: '#7ad4ff' },
    teach: 'Every traveller in this world is given one: a pale horse with a mane like frost and your own initial on its flank, that comes when you call and will carry no one but you. It runs faster than any living horse, which is useful in a world 448 blocks across. The real horse was domesticated on the Eurasian steppe about 5,500 years ago and changed everything about how far people could go.',
    facts: ['A real horse gallops at 40 to 48 km/h; the fastest recorded was 70 km/h over a quarter mile. This one does not care.', 'Horses sleep standing up by locking their knees, and lie down only for deep sleep when another horse keeps watch.', 'Tap the ground with the bridle to call it to you from anywhere, even the far side of the ocean.'] }
];
BC.ANIMAL_BY_ID = {};
BC.ANIMALS.forEach(a => { BC.ANIMAL_BY_ID[a.id] = a; });
